raw.document:
query CurrentUnavailableVariants {
  products(first: 100, query: "status:active") {
    nodes {
      id
      title
      status
      variants(first: 100) {
        nodes {
          id
          title
          inventoryQuantity
          inventoryItem {
            tracked
            inventoryLevels(first: 100) {
              nodes {
                quantities(names: ["available"]) {
                  name
                  quantity
                }
                location {
                  id
                  name
                }
              }
            }
          }
        }
      }
    }
  }
}

